        self._check_secret(secret)
        self._check_level(level)
        plain = self._serialize(value).encode("utf-8")
        cipher = bytes(byte ^ secret[i % len(secret)] for i, byte in enumerate(plain))
        prefix = f"SV1|{self.type_tag}|{level}|{cipher.hex()}"
        mac = hmac.new(secret, prefix.encode(), hashlib.sha256).hexdigest()
